import sys

def solve():
	inp = sys.stdin.readline
	(n, k) = map(int, inp().split())
	d = dict()
	for i in inp():
		d[i] = d.get(i, 0) + 1
	del d['\n']
	pairs = 0
	for i in d:
		pairs += d[i] // 2
	pk = pairs // k
	if n - pk * 2 * k >= k:
		print(pk * 2 + 1)
	else:
		print(pk * 2)

def main():
	for i in range(int(sys.stdin.readline())):
		solve()
main()
